const body = $json.body || {};
const eventType = body.event_type || body.event || null;

// Fixed 2026-09-23 against a REAL LEAD_CATEGORY_UPDATED payload (webhook id 875223,
// event_id 81c48d4a-1670-4ef0-a89a-8a553f60ab7a) - the earlier field paths (body.lead.email,
// body.category.name) were guesses from Smartlead's own docs and were WRONG. Real shape:
// lead_email and campaign_id are top-level (those were already right); name/company info is
// under body.lead_data (not body.lead); category arrives BOTH as a plain string at
// body.category AND as an object at body.lead_data.category ({name, sentiment_type}) -
// prefer the object form for sentiment_type, fall back to the plain string. event_timestamp
// is the real field name for when Smartlead says the event happened (there is no top-level
// "timestamp") - preferred over server-arrival time when present.
const eventTime = body.event_timestamp ? new Date(body.event_timestamp) : new Date();
const date = eventTime.toISOString().slice(0, 10);
const month = date.slice(0, 7);
const leadData = body.lead_data || {};
const categoryObj = leadData.category || {};
const categoryName = categoryObj.name || body.category || null;
const sentimentType = categoryObj.sentiment_type || null;

const TRACKED = ['EMAIL_SENT', 'EMAIL_REPLIED', 'EMAIL_BOUNCED', 'LEAD_CATEGORY_UPDATED'];
const skip = TRACKED.indexOf(eventType) === -1;

return [{ json: {
  skip: skip,
  timestamp: eventTime.toISOString(),
  date: date,
  month: month,
  event_type: eventType,
  campaign_id: body.campaign_id || null,
  lead_email: body.lead_email || leadData.email || null,
  lead_first_name: leadData.first_name || null,
  lead_last_name: leadData.last_name || null,
  category_name: categoryName,
  sentiment_type: sentimentType
} }];
